    else
        isUnlockCollect = checkNumber(dojo.collectNum) >= table.count(FishingUtils.GetAllFishVoByPlaceId(self._data.id))
    end

    local isUnlock, err = FishingUtils.IsCanFishHangUp(self._data.id)
    KTool.SetActive(self.Imglock, not isUnlockPlace)
    KTool.SetActive(self.TxtNumber, isUnlockPlace and not isUnlockCollect)
    if not isUnlockCollect then
        CfUtils.FillText(self.TxtNumber, checkNumber(dojo.collectNum).."/"..table.count(FishingUtils.GetAllFishVoByPlaceId(self._data.id)))
    end

    local isTasking = FishingUtils.IsFishPlaceHasTask(self._data.id)
    local isTaskFinish = FishingUtils.IsFishPlaceTaskFinish(self._data.id)
    KTool.SetActive(self.TxtCommissioned, (isTasking and not isTaskFinish))
    
